import {SignalAlertTracker} from '/signal-alerts.js';
let newsExpanded=false;
let state,tab='radar',symbol='BTC/USD',busy=false,streamConnected=false,lastStreamAt=0;
let rangeCount=window.innerWidth<650?30:58,panOffset=0,crosshair=null,drag=null,renderedSymbol=null,positionsKey='',lastFallbackAt=0,modelOpen=false,diagnostics=null;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(n,d=2)=>n===null||n===undefined||!Number.isFinite(Number(n))?'—':Number(n).toLocaleString('fr-FR',{maximumFractionDigits:d,minimumFractionDigits:d});
const money=n=>num(n,0)+' $',price=(n,s=symbol)=>num(n,s?.includes('EUR')||s?.includes('GBP')?5:2);
const date=t=>t&&Number.isFinite(Date.parse(t))?new Intl.DateTimeFormat('fr-FR',{timeZone:'Africa/Casablanca',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(t)):'—';
const time=t=>t&&Number.isFinite(Date.parse(t))?new Intl.DateTimeFormat('fr-FR',{timeZone:'Africa/Casablanca',hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date(t)):'—';
const badge=s=>'<span class="badge '+s.toLowerCase()+'">'+esc(s)+'</span>';
const names={'BTC/USD':['BTC','Bitcoin','₿'],'EUR/USD':['EUR/USD','EUR / USD','€'],'GBP/USD':['GBP/USD','GBP / USD','£'],'XAU/USD':['GOLD','Gold','◇'],'NDX':['NASDAQ','Nasdaq 100','↗']};
const selected=()=>state?.radar.find(m=>m.symbol===symbol);
const decision=m=>!pushFresh()?{...m?.decision,side:'HOLD',reason:'Connexion au flux interrompue',confidence:{...m?.decision?.confidence,percent:null,classProbs:null,status:'stale',reason:'Connexion au flux interrompue'}}:m?.decision??{side:'HOLD',strategyName:'Analyse en cours',confidence:{percent:null,status:'insufficient',reason:'Modèle en préparation'}};
const confirmed=decision;
const pushFresh=()=>streamConnected&&lastStreamAt>0&&Date.now()-lastStreamAt<5000;
function notify(text,error=false){const e=$('#notice');e.hidden=false;e.className='message'+(error?' error':'');e.textContent=text;setTimeout(()=>e.hidden=true,6500);}
async function api(url,value){const r=await fetch(url,value===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-Terminal-Token':state.token},body:JSON.stringify(value)}),j=await r.json();if(!r.ok)throw Error(j.error||'Connexion interrompue');return j;}
function swap(selector,html){const e=$(selector);if(e&&e.innerHTML!==html){const opens=[...e.querySelectorAll('details[data-key][open]')].map(d=>d.dataset.key);e.innerHTML=html;e.querySelectorAll('details[data-key]').forEach(d=>d.open=opens.includes(d.dataset.key));}}
function feedLabel(m=selected()){if(!pushFresh())return lastStreamAt?'Reconnexion…':'Connexion…';if(m?.feed?.status==='live')return 'Temps réel';if(m?.feed?.status==='closed'||m?.provenance?.marketOpen===false)return 'Marché fermé';if(m?.feed?.status==='stale')return 'Cotation ancienne';if(m?.quote)return 'Instantané · '+time(m.quote.eventTime??m.quote.receivedAt);return m?.bars?.length?'Historique':'Connexion…';}
function blocked(m){const d=decision(m);return !pushFresh()?'Connexion au flux en cours':!state.profile.confirmed?'Configurer le challenge':!m?.eligible?'Instrument hors profil':!m?.live?'Cotation en direct indisponible':d.side==='HOLD'?'Aucune entrée confirmée':m.model?.status==='pending'?'Analyse en cours':null;}
function setStatus(){if(!state)return;const m=selected(),e=$('#session-state');if(e){e.className='feed-chip '+(pushFresh()&&m?.feed?.status==='live'?'live':m?.feed?.status==='stale'?'stale':'');e.innerHTML='<i></i>'+esc(feedLabel(m));}if(m&&!pushFresh()){swap('#signal-card',signalCard(m));updateInsights(m);if(modelOpen)swap('#model-sheet',modelSheet());}const order=$('#paper-open');if(order)order.disabled=blocked(m)!==null;}
function accept(next){state=next;processSignalAlerts(next);if(!selected())symbol=state.radar[0]?.symbol;setStatus();if(tab==='radar'){if(!$('#desk')||renderedSymbol!==symbol)render();else updateDesk();}else if(tab==='journal'&&JSON.stringify(state.positions)!==positionsKey)render();}
async function load(){accept(await api('/api/state'));}
function heading(name,sub=''){return '<div class="page-heading"><h1>'+esc(name)+'</h1><span class="subtle">'+esc(sub)+'</span></div>';}
function markets(){return '<div class="market-switcher" role="tablist" aria-label="Marchés">'+Object.entries(names).map(([s,n])=>'<button role="tab" aria-selected="'+(s===symbol)+'" class="market-tab '+(s===symbol?'active':'')+'" data-symbol="'+s+'"><span class="market-symbol">'+n[2]+'</span>'+n[0]+'</button>').join('')+'</div>';}
function instrument(m){const n=names[symbol],px=m.quote?.price??m.bars.at(-1)?.close,last=m.bars.at(-1)?.close,change=last&&px?(px/last-1)*100:null;return '<div class="quote-name"><span class="asset-icon">'+n[2]+'</span><div><h1>'+n[1]+'</h1><small>'+esc(m.source??'Connexion au fournisseur')+'</small></div></div><div class="quote-value"><b>'+price(px)+'</b><small title="Variation depuis la dernière clôture 15 min" class="'+(change>0?'up':change<0?'down':'')+'">'+(change===null?'—':(change>0?'+':'')+num(change)+' %')+'</small></div>';}
function displayedConfidence(d){
  const c=d.confidence??{},active=['BUY','SELL'].includes(d.side),candidate=d.confidenceGate?.candidateSide;
  if(active)return {percent:Number.isFinite(c.percent)?c.percent:null,label:'Direction à 1 h ⓘ'};
  const direction=candidate==='BUY'?'UP':candidate==='SELL'?'DOWN':null,p=direction?c.classProbs?.[direction]:null;
  if(c.status==='estimate'&&Number.isFinite(p)&&p>=0&&p<=1)return {percent:Math.round(p*1000)/10,label:'Candidat '+candidate+' ⓘ'};
  return {percent:null,label:c.status==='unvalidated'?'Modèle non retenu':c.status==='estimate'?'Aucun déclencheur':'Analyse indisponible'};
}
function signalCard(m){const d=decision(m),side=['BUY','SELL'].includes(d.side)?d.side:'HOLD',c=d.confidence??{},display=displayedConfidence(d),pct=display.percent,active=side!=='HOLD',block=blocked(m),ring='<div class="confidence-ring" aria-hidden="true"><svg viewBox="0 0 60 60"><circle cx="30" cy="30" r="25" fill="none" stroke="#20242e" stroke-width="4"/><circle cx="30" cy="30" r="25" fill="none" stroke="#477bff" stroke-width="4" stroke-linecap="round" stroke-dasharray="'+(157*(pct??0)/100)+' 157"/></svg><span>↗</span></div>';return '<div class="action-block"><span class="direction-icon '+side.toLowerCase()+'">'+(side==='BUY'?'↗':side==='SELL'?'↘':'Ⅱ')+'</span><div><div class="decision-side '+side.toLowerCase()+'">'+side+'</div><div class="strategy-caption"><button data-model title="Voir la méthode">'+esc(d.strategyName??'Analyse du marché')+' ↗</button></div></div></div><div class="confidence-block">'+ring+'<div><div class="confidence-number">'+num(pct,1)+'<span>%</span></div><button class="confidence-label" data-model title="'+esc(c.referenceTime&&c.horizonEndAt?'Mouvement net entre '+time(c.referenceTime)+' et '+time(c.horizonEndAt):'Direction nette à 1 h')+'">'+esc(display.label)+'</button></div></div><div class="execution"><div class="levels">'+[['ENTRÉE',d.entry],['STOP',d.stop],['OBJECTIF',d.target]].map(([k,v])=>'<div><small>'+k+'</small><b>'+price(active?v:null)+'</b></div>').join('')+'</div><button class="trade-button" id="paper-open" '+(block?'disabled':'')+' title="'+esc(block??'Simuler '+side+' en paper')+'" aria-label="Simuler une entrée paper">↗</button></div>';}
function footer(m){return '<span>'+esc(m.quote?'Dernière cotation · '+(m.feed?.status==='live'?time(m.quote.eventTime??m.quote.receivedAt):date(m.quote.eventTime??m.quote.receivedAt)):'Dernière clôture · '+date(m.asOf))+'</span><div class="foot-actions"><span>OHLC · 15 min</span><button data-model>Méthode ↗</button></div>';}
function modelSheet(){const m=selected(),d=decision(m),c=d.confidence??{},model=diagnostics?.markets?.find(x=>x.symbol===symbol&&x.version===m.model?.version&&x.source===m.source),probs=c.classProbs;return '<div class="sheet-head"><h2>Le signal, en clair</h2><button data-dismiss-model aria-label="Fermer les détails">×</button></div><div class="model-body"><strong>'+esc(d.reason??c.reason)+'</strong><br>BUY et SELL exigent un modèle dont l’erreur est inférieure à la référence sur le test historique et une estimation directionnelle strictement supérieure à 60 %. Sinon, le signal reste HOLD.<br>Une règle est choisie selon le régime du marché. Son entrée est vérifiée sur bougie clôturée et filtrée par la tendance H1.<br><br>Le pourcentage estime '+(c.class==='UP'?'une hausse nette':c.class==='DOWN'?'une baisse nette':'un mouvement neutre')+(c.referenceTime&&c.horizonEndAt?' entre la clôture de '+time(c.referenceTime)+' et '+time(c.horizonEndAt):' sur '+(c.horizonMinutes??60)+' minutes')+'. Le seuil combine 0,35 ATR et une hypothèse de coûts aller-retour. Il ne mesure pas le taux de trades gagnants.</div><div class="probabilities">'+[['UP','Hausse'],['DOWN','Baisse'],['FLAT','Neutre']].map(([k,n])=>'<div>'+n+'<b>'+num(probs?.[k]===undefined?null:probs[k]*100,1)+' %</b></div>').join('')+'</div><div class="model-meta"><span>Entraînement · '+(c.sample??0)+' observations</span><span>Validation · '+(c.calibrationSample??0)+'</span><span>Test séparé · '+(c.testSample??0)+'</span><span>'+esc(c.status==='estimate'?'Estimation historique':c.reason??'Analyse en cours')+'</span></div>'+(model?.test?'<div class="model-meta"><span>Brier · '+num(model.test.brier,3)+'</span><span>Référence · '+num(model.test.baselineBrier,3)+'</span><span>Erreur de calibration · '+num(model.test.calibrationError,3)+'</span></div>':'')+aiModelDetails(m,c,model)+modelRobustness(model);}
function modelRobustness(model){
  const audit=model?.test?.robustness;if(audit?.status!=='available')return '';
  const clean=audit.nonOverlapping;
  return '<details class="ai-method" data-key="model-robustness"><summary>Stabilité du test</summary><div class="model-meta"><span>Horizons sans chevauchement · '+clean.sample+'</span><span>Brier · '+num(clean.brier,3)+'</span><span>Référence · '+num(clean.baselineBrier,3)+'</span></div><div class="ai-comparison">'+audit.segments.map(row=>'<div><span>Période '+row.part+' · '+row.sample+' observations</span><b>'+num(row.brier,3)+'</b></div>').join('')+'</div><p>Trois périodes du test, modèle figé. Retirer le chevauchement ne rend pas les observations indépendantes. Ces mesures ne sont pas un taux de trades gagnants et ne choisissent pas le modèle.</p></details>';
}
function algorithmName(algorithm){return algorithm==='regularized-lda'?'LDA régularisée':algorithm==='neural-network'?'Réseau neuronal':algorithm==='weighted-knn'?'Analogues kNN':algorithm==='regularized-qda'?'QDA régularisée':algorithm==='multinomial-logistic'?'Régression logistique':'En préparation';}
function aiStatusLabel(m){const c=decision(m).confidence??{};return c.status==='unvalidated'?'Modèle non retenu':c.algorithm?algorithmName(c.algorithm):m.feed?.status==='closed'?'Marché fermé':['stale','unavailable','error'].includes(c.status)?'Analyse indisponible':'Calcul en cours';}
function aiProbabilities(m){
  const c=decision(m).confidence??{},ready=pushFresh()&&c.status==='estimate'&&c.classProbs;
  return [['UP','Hausse'],['DOWN','Baisse'],['FLAT','Neutre']].map(([key,label])=>{
    const probability=ready?c.classProbs[key]:null;
    return '<div class="ai-prob '+key.toLowerCase()+'"><span>'+label+'</span><b>'+num(Number.isFinite(probability)?probability*100:null,1)+'<small> %</small></b><i><em style="width:'+Math.max(0,Math.min(100,(probability??0)*100))+'%"></em></i></div>';
  }).join('');
}
function aiScanRows(){
  return [...(state.radar??[])].sort((a,b)=>Number(decision(a).side==='HOLD')-Number(decision(b).side==='HOLD')).map(m=>{
    const d=decision(m),c=d.confidence??{},display=displayedConfidence(d),available=pushFresh()&&c.status==='estimate'&&Number.isFinite(display.percent),side=available?d.side:'HOLD',label=m.feed?.status==='closed'?'Fermé':c.status==='unvalidated'?'Non retenu':!available?'En attente':side,percent=available?num(display.percent,1)+' %':'—';
    return '<button class="ai-scan-market '+(m.symbol===symbol?'selected ':'')+side.toLowerCase()+'" data-symbol="'+esc(m.symbol)+'" title="'+esc(d.reason??'Analyse indisponible')+'"><span>'+esc(m.symbol)+'</span><b>'+esc(label)+'</b><small>'+percent+(available&&side==='HOLD'?' · candidat '+esc(d.confidenceGate?.candidateSide):'')+'</small></button>';
  }).join('');
}
function aiModelDetails(m,c,model){
  const candidates=model?.selection?.candidates??[],neighbours=c.neighboursDetail??[],active=model?.selection?.selected??c.algorithm,k=model?.selection?.selectedK??c.neighboursCount,shrinkage=model?.selection?.selectedShrinkage,hiddenUnits=model?.selection?.selectedHiddenUnits;
  if(!c.algorithm&&!candidates.length)return '';
  return '<section class="ai-method"><h3>IA locale · '+esc(algorithmName(model?.algorithm??c.algorithm))+(c.algorithm==='weighted-knn'?' · '+(c.neighboursCount??0)+' analogues':'')+'</h3>'+(candidates.length?'<div class="ai-comparison">'+candidates.map(row=>{
    const chosen=row.algorithm===active&&(row.algorithm!=='weighted-knn'||row.k===k)&&(!['regularized-qda','regularized-lda'].includes(row.algorithm)||row.shrinkage===shrinkage)&&(row.algorithm!=='neural-network'||row.hiddenUnits===hiddenUnits);
    return '<div class="'+(chosen?'chosen':'')+'"><span>'+esc(algorithmName(row.algorithm))+(row.k?' · k='+row.k:'')+(['regularized-qda','regularized-lda'].includes(row.algorithm)?' · α='+num(row.shrinkage,2):'')+(row.algorithm==='neural-network'?' · '+row.hiddenUnits+' neurones':'')+(chosen?' ✓':'')+'</span><b>'+num(row.brier,3)+'</b></div>';
  }).join('')+'</div><p>Un modèle retenu sur validation chronologique · Brier plus bas = mieux. Le test séparé ne choisit pas le modèle.</p>'+(candidates.some(row=>row.algorithm==='regularized-qda')?'<p>LDA : covariance partagée entre directions. QDA : covariance propre à chaque direction, régularisée par α. Probabilités ajustées en température sur validation.</p>':''):'')+(neighbours.length?'<h4>Configurations historiques proches</h4><div class="ai-neighbours">'+neighbours.slice(0,5).map(row=>'<div title="'+esc('Issue observée à '+date(row.labelEndTime)+' · distance standardisée '+num(row.distance,3))+'"><time>'+date(row.time)+'</time><span>'+esc(row.label==='UP'?'Hausse':row.label==='DOWN'?'Baisse':'Neutre')+'</span><small>d '+num(row.distance,2)+'</small></div>').join('')+'</div><p>'+esc(m.source)+' · rendements nets à 1 h après coûts hypothétiques ; ce ne sont pas des trades gagnants.</p>':'')+'</section>';
}
function evidenceFor(m){const e=m.strategyEvidence;return e&&e.strategy===decision(m).strategy&&['available','insufficient'].includes(e.status)?e:null;}
function evidenceLabel(m){const e=evidenceFor(m);return e?e.sample+' trades'+(e.sample<e.minimumSample?' · échantillon court':''):m.model?.status==='pending'?'En calcul':'Indisponible';}
function evidenceDetails(m){
  const e=evidenceFor(m);if(!e)return '<p>Résultats historiques indisponibles pour cette règle.</p>';
  const signed=value=>Number.isFinite(value)?(value>0?'+':'')+num(value,2)+' R':'—';
  return '<div class="evidence-title">'+esc(e.name)+'</div><div class="evidence-grid"><div><span>Trades gagnants</span><b>'+num(e.winRate,1)+'<small> %</small></b></div><div><span>Espérance / trade</span><b>'+signed(e.expectancy)+'</b></div><div><span>Résultat net</span><b>'+signed(e.totalR)+'</b></div><div><span>Perte depuis un sommet</span><b>'+num(e.maxDrawdownR,2)+'<small> R</small></b></div></div>'+(e.winInterval?'<p>Intervalle à 95 % : '+num(e.winInterval[0],1)+'–'+num(e.winInterval[1],1)+' %.</p>':'')+'<p>Règle seule · test final · coûts hypothétiques'+(e.cost?' ('+num(e.cost.feeBps,0)+' pb de frais + '+num(e.cost.slippageBps,0)+' pb de glissement par côté)':'')+'.</p>'+(e.tradeFrom&&e.tradeTo?'<p>Trades simulés du '+date(e.tradeFrom)+' au '+date(e.tradeTo)+'.</p>':'');
}
function replayLabel(m){const r=m.replay;return r?.status==='unavailable'?'Indisponible':r?.metrics?r.metrics.n+' trades simulés':r?.status==='pending'?'En calcul':'Indisponible';}
function replayDetails(m){
  const r=m.replay;if(!r?.metrics||r.status==='unavailable')return '<p>'+esc(r?.reason??'Replay du moteur indisponible ou en calcul.')+'</p>';
  const q=r.metrics,c=r.counts??{},signed=v=>Number.isFinite(v)?(v>0?'+':'')+num(v,2)+' R':'—';
  return '<div class="evidence-title">Moteur complet · test chronologique</div><div class="evidence-grid"><div><span>Trades simulés</span><b>'+q.n+'</b></div><div><span>Gagnants historiques</span><b>'+num(q.winRate,1)+'<small> %</small></b></div><div><span>Espérance nette</span><b>'+signed(q.expectancy)+'</b></div><div><span>Résultat net</span><b>'+signed(q.totalR)+'</b></div></div><p>'+esc(r.reason)+'</p><div class="replay-blocks">'+[['Sans déclencheur',c.noSetup],['Seuil 60 %',c.confidence],['Tendance H1',c.h1],['Niveaux / prix',(c.levels??0)+(c.price??0)],['Frais / glissement',c.costs],['Issues non connues',c.censored]].map(([label,n])=>'<span>'+label+'<b>'+num(n,0)+'</b></span>').join('')+'</div>'+(r.stress?.metrics?'<p>Coûts ×2 : '+r.stress.metrics.n+' trades · résultat '+signed(r.stress.metrics.totalR)+'.</p>':'')+(r.recentTrades?.length?'<div class="replay-trades">'+r.recentTrades.map(t=>'<div><time>'+date(t.time)+'</time><b>'+esc(t.side)+'</b><span>'+signed(t.r)+'</span><small>'+esc(t.reason)+'</small></div>').join('')+'</div>':'')+'<p>Modèle figé après '+date(r.modelCalibratedThrough)+' · horizon '+(r.horizonBars*15)+' min · une position à la fois. Le contrôle final du modèle n’est pas réappliqué au passé.</p><p>'+esc((r.assumptions??[]).join(' · '))+'. Ce replay ne constitue pas le suivi des signaux reçus en direct.</p>';
}
function aiPanel(m){
  return '<section class="ai-panel" aria-label="Analyse IA"><div class="ai-heading"><h2><i>✦</i> IA locale</h2><button data-model id="ai-model-label">'+esc(aiStatusLabel(m))+' ↗</button></div><div class="ai-probabilities" id="ai-probabilities" aria-label="Probabilités de mouvement net à une heure">'+aiProbabilities(m)+'</div><details class="ai-scanner" data-key="ai-scanner"><summary><span>Scanner <b>5 marchés</b></span><span>Automatique <i>＋</i></span></summary><div class="ai-scan-list" id="ai-scan-list">'+aiScanRows()+'</div></details><details class="ai-evidence" data-key="historical-evidence"><summary><span>Test historique</span><span id="evidence-label">'+esc(evidenceLabel(m))+'</span></summary><div id="evidence-details">'+evidenceDetails(m)+'</div></details><details class="ai-evidence" data-key="decision-checks"><summary><span>Contrôles du signal</span><span>7 vérifications</span></summary><div id="decision-check-details">'+decisionCheckRows(m)+'</div></details><details class="ai-evidence" data-key="engine-replay"><summary><span>Replay du moteur</span><span id="replay-label">'+esc(replayLabel(m))+'</span></summary><div id="replay-details">'+replayDetails(m)+'</div></details></section>';
}
function updateAI(m){
  swap('#replay-label',esc(replayLabel(m)));swap('#replay-details',replayDetails(m));swap('#decision-check-details',decisionCheckRows(m));
  swap('#evidence-label',esc(evidenceLabel(m)));swap('#evidence-details',evidenceDetails(m));swap('#ai-model-label',esc(aiStatusLabel(m))+' ↗');swap('#ai-probabilities',aiProbabilities(m));swap('#ai-scan-list',aiScanRows());
}

const ALERT_STORAGE='orivane.alerts.v1';
function readAlertSettings(){try{const value=JSON.parse(localStorage.getItem(ALERT_STORAGE)??'{}');return {enabled:value?.enabled===true,seenIds:Array.isArray(value?.seenIds)?value.seenIds:[]};}catch{return {enabled:false,seenIds:[]};}}
const alertSettings=readAlertSettings();
let alertsEnabled=alertSettings.enabled,alertAudio=null;
const alertTracker=new SignalAlertTracker(alertSettings);
function validStreamState(next){return typeof next?.token==='string'&&next.profile&&next.account&&Array.isArray(next.positions)&&Array.isArray(next.radar)&&next.radar.length===5&&new Set(next.radar.map(m=>m?.symbol)).size===5&&next.radar.every(m=>Object.hasOwn(names,m?.symbol)&&Array.isArray(m?.bars)&&['BUY','SELL','HOLD'].includes(m?.decision?.side)&&m?.decision?.confidence&&typeof m?.feed?.status==='string');}
function acceptStreamState(next){streamConnected=true;lastStreamAt=Date.now();accept(next);}
function saveAlertSettings(){try{localStorage.setItem(ALERT_STORAGE,JSON.stringify({enabled:alertsEnabled,seenIds:alertTracker.seenIds()}));}catch{}}
function prepareAlertAudio(){try{const Audio=window.AudioContext??window.webkitAudioContext;if(Audio){alertAudio??=new Audio();alertAudio.resume().catch(()=>{});}}catch{}}
function playAlertAudio(){try{if(alertAudio?.state!=='running')return;const tone=alertAudio.createOscillator(),gain=alertAudio.createGain(),start=alertAudio.currentTime;tone.type='sine';tone.frequency.setValueAtTime(740,start);tone.frequency.setValueAtTime(990,start+.13);gain.gain.setValueAtTime(0,start);gain.gain.linearRampToValueAtTime(.055,start+.025);gain.gain.exponentialRampToValueAtTime(.001,start+.32);tone.connect(gain);gain.connect(alertAudio.destination);tone.start(start);tone.stop(start+.34);tone.onended=()=>{tone.disconnect();gain.disconnect();};}catch{}}
function processSignalAlerts(next){const previous=alertTracker.seenIds().join(','),alerts=alertTracker.consume(next,{streamFresh:pushFresh()});if(previous!==alertTracker.seenIds().join(','))saveAlertSettings();if(!alerts.length)return;const first=alerts[0];notify(first.symbol+' · '+first.side+' · '+num(first.confidencePercent,1)+' %'+(alerts.length>1?' · '+alerts.length+' nouveaux signaux':''));playAlertAudio();}
function alertButton(){return '<button class="alert-toggle '+(alertsEnabled?'enabled':'')+'" data-alert-toggle aria-pressed="'+alertsEnabled+'" title="Nouveaux BUY/SELL confirmés > 60 %, navigateur ouvert">'+(alertsEnabled?'◉ Alertes on':'○ Alertes off')+'</button>';}
function ageLabel(ms){if(!Number.isFinite(ms)||ms<0)return '—';if(ms<1000)return '< 1 s';if(ms<60000)return Math.floor(ms/1000)+' s';if(ms<3600000)return Math.floor(ms/60000)+' min';return num(ms/3600000,1)+' h';}
function healthState(row){return !pushFresh()?'offline':row.state;}
function healthLabel(status){return {live:'Direct',snapshot:'Instantané',closed:'Fermé',stale:'Ancien',connecting:'Connexion',offline:'Déconnecté',error:'Erreur',historical:'Historique',unavailable:'Indisponible'}[status]??'Indisponible';}
function healthSummary(){if(!pushFresh())return 'Reconnexion…';const rows=state.marketHealth??[],direct=rows.filter(row=>row.state==='live').length,snapshots=rows.filter(row=>row.state==='snapshot').length;return rows.length?direct+' directs'+(snapshots?' · '+snapshots+' instantané'+(snapshots>1?'s':''):''):'Connexion…';}
function healthRows(){return (state.marketHealth??[]).map(row=>{const status=healthState(row),age=pushFresh()?ageLabel(row.quoteAgeMs):'—',spread=pushFresh()&&Number.isFinite(row.spreadBps)?num(row.spreadBps,1)+' pb':'—',model=row.modelStatus==='ready'?'IA prête':row.modelStatus==='pending'?'IA en calcul':'IA indisponible',details='Reçu : '+date(row.quoteAt)+' · Événement : '+date(row.quoteEventAt)+' · Dernière clôture : '+date(row.lastClosedAt)+' · '+row.barCount+' bougies · '+row.consecutiveClosedBars+' consécutives';return '<div class="health-row" title="'+esc(details)+'"><div><b>'+esc(names[row.symbol]?.[0]??row.symbol)+'</b><small>'+esc(row.source??'Source indisponible')+'</small></div><span class="health-state '+esc(status)+'"><i></i>'+esc(healthLabel(status))+'</span><span class="health-age">'+esc(age)+'</span><span class="health-spread">'+esc(spread)+'</span><small class="health-model">'+esc(model)+'</small></div>';}).join('')||'<div class="insight-empty">Connexion aux sources…</div>';}
function followupItems(m){return (state.signalFollowup?.items??[]).filter(item=>item.symbol===m.symbol);}
function followupLabel(m){const rows=followupItems(m),active=rows.filter(item=>item.status==='watching').length;return active?active+' en observation':rows.length?rows.length+' récents':'Dès le prochain signal';}
function followupRows(m){const rows=followupItems(m).slice(0,6);if(!rows.length)return '<div class="insight-empty">Aucun nouveau signal suivi sur ce marché.</div>';return rows.map(item=>{const status={watching:'En observation','target-observed':'Objectif observé','stop-observed':'Stop observé',expired:'Horizon terminé'}[item.status]??'Indisponible',hit=Number.isFinite(item.observedPrice),detail='Entrée '+price(item.entry,item.symbol)+' · Stop '+price(item.stop,item.symbol)+' · Objectif '+price(item.target,item.symbol)+' · Horizon '+time(item.horizonEndAt);return '<div class="followup-row" title="'+esc(detail)+'"><div><span class="idea-side '+(item.side==='SELL'?'sell':'buy')+'">'+esc(item.side)+' · '+num(item.confidencePercent,1)+' %</span><small>'+esc(item.strategyName??item.strategy)+' · '+time(item.signalObservedAt)+'</small></div><div class="followup-result '+esc(item.status)+'"><b>'+esc(status)+'</b><small>'+(hit?price(item.observedPrice,item.symbol)+' · '+time(item.observedAt):item.status==='expired'?'Sans toucher observé':'Horizon '+time(item.horizonEndAt))+'</small></div></div>';}).join('');}
function formingProgress(m){const row=state.marketHealth?.find(row=>row.symbol===m.symbol),value=pushFresh()?row?.formingBarProgressPct:null;return Number.isFinite(value)?'<span>Bougie 15m</span><i><em style="width:'+Math.max(0,Math.min(100,value))+'%"></em></i><b>'+num(value,0)+' %</b>':'';}
function technologyPanel(m){return '<section class="technology-panel" aria-label="Observation en direct"><div class="technology-heading"><h2><i>⌁</i> Observation</h2><div id="alert-control">'+alertButton()+'</div></div><details class="technology-detail" data-key="health"><summary><span>État des flux</span><span id="health-summary">'+esc(healthSummary())+'</span></summary><div class="health-columns"><span>Source</span><span>État</span><span>Âge reçu</span><span>Spread</span><span>Modèle</span></div><div id="health-rows">'+healthRows()+'</div><div class="forming-progress" id="forming-progress">'+formingProgress(m)+'</div></details><details class="technology-detail" data-key="followup"><summary><span>Suivi des signaux · '+esc(names[m.symbol]?.[0]??m.symbol)+'</span><span id="followup-label">'+esc(followupLabel(m))+'</span></summary><div id="followup-rows">'+followupRows(m)+'</div><p class="followup-note">Niveaux touchés sur les cotations reçues · distincts des trades paper.</p></details></section>';}
function updateTechnology(m){swap('#alert-control',alertButton());swap('#health-summary',esc(healthSummary()));swap('#health-rows',healthRows());swap('#forming-progress',formingProgress(m));swap('#followup-label',esc(followupLabel(m)));swap('#followup-rows',followupRows(m));}
document.addEventListener('click',e=>{if(!e.target.closest('[data-alert-toggle]'))return;alertsEnabled=!alertsEnabled;alertTracker.setEnabled(alertsEnabled);if(alertsEnabled)prepareAlertAudio();saveAlertSettings();swap('#alert-control',alertButton());notify(alertsEnabled?'Alertes activées · navigateur ouvert.':'Alertes désactivées.');});

function ideaCards(m){
  const rows=m.ideas??[];
  if(!rows.length)return '<div class="insight-empty">'+esc(m.provenance?.marketOpen===false||m.feed?.status==='closed'?'Marché fermé · aucune idée active':'Aucun scénario compatible avec les conditions actuelles.')+'</div>';
  return rows.map(idea=>{
    const d=decision(m),live=pushFresh()&&idea.live&&!idea.stale,confirmed=live&&idea.confirmed&&d.side===idea.side&&d.strategy===idea.strategy&&d.confidence?.percent>60,status=!live?'Historique':confirmed?'Confirmé':'À surveiller',side=idea.side==='SELL'?'SELL':'BUY',directionLabel=confirmed?side:side==='BUY'?'Scénario haussier':'Scénario baissier';
    const trigger=idea.entryTrigger??idea.trigger,condition=idea.condition??'Conditions à confirmer',levels=confirmed?'<div class="idea-levels"><span>Stop <b>'+price(idea.stop)+'</b></span><span>Objectif <b>'+price(idea.target)+'</b></span></div>':'',timing=confirmed?'Confirmé à '+time(idea.confirmationAt):'Clôture analysée '+time(idea.referenceClosedAt)+' · prochaine clôture '+time(idea.confirmationAt);
    return '<article class="idea-card '+(confirmed?'ready':'')+'"><div class="idea-top"><span class="idea-side '+side.toLowerCase()+'">'+(side==='BUY'?'↗':'↘')+' '+directionLabel+'</span><span class="idea-state '+(confirmed?'ready':'')+'">'+status+'</span></div><h3>'+esc(idea.strategyName)+'</h3><div class="idea-trigger" title="'+esc(condition)+'">'+(Number.isFinite(trigger)?esc(confirmed?'Entrée confirmée':idea.triggerLabel??'Clôture à franchir')+' <b>'+price(trigger)+'</b>':esc(condition))+'</div>'+levels+'<details class="idea-detail" data-key="'+esc(idea.id??idea.strategy)+'"><summary>'+(confirmed?'Conditions & invalidation':'Conditions de confirmation')+'</summary><p>'+esc(condition)+'</p><p>'+esc((idea.blockingReasons??[]).join(' · ')||(confirmed?'Conditions de clôture réunies':'Confirmation en clôture et confiance > 60 % requises'))+'</p><p>'+esc(idea.riskBasis??'')+'</p><p>'+esc(timing)+'<br>'+esc(idea.source)+'</p></details></article>';
  }).join('');
}
function newsForMarket(){
  const news=state.news??{},rows=news.items??news.articles??[];
  return rows.filter(n=>{const markets=n.symbols??n.markets;return !markets?.length||markets.includes(symbol);});
}
function newsRows(){
  const rows=newsForMarket().slice(0,newsExpanded?12:3);
  if(!rows.length)return '<div class="insight-empty">'+esc(state.news?.status==='loading'?'Chargement des sources…':'Aucune actualité récente disponible pour ce marché.')+'</div>';
  return rows.map(n=>{
    let url;try{url=new URL(n.url);if(url.protocol!=='https:')return '';}catch{return '';}
    const published=n.publishedAt??n.publicationTime,source=typeof n.source==='object'?n.source.name:n.source??n.publisher;
    if(!Number.isFinite(Date.parse(published)))return '';
    const old=Date.now()-Date.parse(published)>7*86400000;
    return '<a class="news-item" href="'+esc(url.href)+'" title="'+esc('Publié le '+date(published)+(n.receivedAt?' · reçu le '+date(n.receivedAt):''))+'" target="_blank" rel="noopener noreferrer"><div class="news-meta"><span>'+esc((source??'Source')+(n.sourceKind==='publisher'?' · média':'')+(n.cached?' · cache':''))+'</span><time datetime="'+esc(published)+'">'+esc(old?new Intl.DateTimeFormat('fr-FR',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(published)):date(published))+'</time></div><h3>'+esc(n.title??n.headline)+'</h3><span class="news-arrow" aria-hidden="true">↗</span></a>';
  }).join('');
}
function newsStatus(){const n=state.news;return !n?'Connexion…':n.status==='stale'?'Cache ancien':n.status==='error'||n.status==='unavailable'?'Indisponible':(n.updatedAt??n.fetchedAt)?'MAJ '+time(n.updatedAt??n.fetchedAt):'Sources datées';}
function catalogRows(m){
  return (state.strategyCatalog??m.signals?.map(s=>({id:s.strategy,name:s.strategyName,description:''}))??[]).map(rule=>{
    const signal=m.signals?.find(s=>s.strategy===rule.id),d=decision(m),chosen=d.strategy===rule.id,technical=pushFresh()&&m.feed?.status==='live'&&signal&&signal.side!=='HOLD',active=technical&&chosen&&d.side===signal.side&&d.confidence?.percent>60;
    return '<details class="catalog-rule" data-key="'+esc(rule.id)+'"><summary><span><i class="'+(chosen?'chosen':'')+'"></i>'+esc(rule.name)+'</span><b class="'+(active?signal.side.toLowerCase():'')+'">'+(active?signal.side:technical?'Critères ✓':'En attente')+'</b></summary><div class="catalog-info"><p>'+esc(rule.description)+'</p>'+((signal?.checks??[]).length?'<ul>'+signal.checks.map(c=>'<li><span>'+esc(c.label)+'</span><em>'+ (c.passed?'✓':'—')+'</em></li>').join('')+'</ul>':'')+'<p class="catalog-reason">'+esc(chosen?d.reason:technical?'Critères techniques réunis · signal soumis au routeur, au filtre H1 et à une confiance > 60 %':signal?.reason??'Analyse en cours')+'</p></div></details>';
  }).join('');
}
function observedRows(){const history=state.observedSignals??state.signalHistory??[],items=Array.isArray(history)?history:history.items??[],rows=items.filter(s=>s.symbol===symbol&&s.policy===state.signalPolicy?.id&&s.confidencePercent>60).slice(0,8);return rows.length?rows.map(s=>'<div class="observed-signal" title="'+esc(s.source)+' · clôture '+time(s.signalTime)+'"><span class="idea-side '+String(s.side).toLowerCase()+'">'+esc(s.side)+' · '+num(s.confidencePercent,1)+' %</span><span>'+esc(s.strategyName??s.strategy)+'</span><time>'+date(s.observedAt??s.time)+'</time></div>').join(''):'<div class="insight-empty">Les prochains signaux confirmés avec une confiance > 60 % apparaîtront ici.'+(history.monitoringSince?' Observation depuis '+date(history.monitoringSince)+'.':'')+'</div>';}
function decisionCheckRows(m){const report=m.decisionChecks;if(!pushFresh())return '<p>Connexion interrompue : contrôles en attente.</p>';if(!report)return '<p>Contrôles en préparation.</p>';return '<div class="replay-blocks">'+report.checks.map(c=>'<span title="'+esc(c.detail)+'">'+esc(c.label)+'<b>'+({passed:'✓',blocked:'Bloqué',unavailable:'—'}[c.status]??'—')+'</b></span>').join('')+'</div><p>'+esc(report.reason)+'</p>'+(report.candleQuality?'<p title="'+esc(report.candleQuality.reason)+'">Fenêtre récente : '+report.candleQuality.scanned+' bougies · '+(report.candleQuality.status==='complete'?'consécutives':report.candleQuality.status==='gaps'?report.candleQuality.gaps+' interruptions':report.candleQuality.status==='invalid'?'incohérente':'indisponible')+'.</p>':'');}
function holdContext(m){const h=m.holdReason,d=decision(m);if(d.side!=='HOLD')return '<span>Signal confirmé · clôture '+time(h?.lastClosedAt??d.time)+'</span><small>Seuil > 60 %</small>';return '<span>'+esc(d.reason??h?.reason??'Analyse en cours')+'</span><small title="Dernière clôture analysée : '+time(h?.lastClosedAt??m.asOf)+'">Seuil > 60 % · '+time(h?.lastClosedAt??m.asOf)+'</small>';}
function insights(m){return aiPanel(m)+technologyPanel(m)+'<section class="insights-grid" aria-label="Idées et actualités"><section class="insight-panel ideas-panel"><div class="insight-heading"><h2>Idées du marché</h2><span>PLANS · 15m</span></div><div class="idea-list" id="idea-list">'+ideaCards(m)+'</div></section><section class="insight-panel news-panel"><div class="insight-heading"><h2>Actualités</h2><span id="news-status">'+newsStatus()+'</span></div><div class="news-list" id="news-list">'+newsRows()+'</div><button class="news-more" data-news-more>'+ (newsExpanded?'Réduire':'Toutes les actualités')+' ↗</button></section></section><details class="strategy-library" id="strategy-library"><summary><span>Stratégies <b id="strategy-count">'+(state.strategyCatalog?.length??m.signals?.length??0)+'</b></span><span>Règles & déclencheurs <i>＋</i></span></summary><div class="catalog-grid" id="strategy-catalog">'+catalogRows(m)+'</div></details><details class="strategy-library observed-library"><summary><span>Signaux observés</span><span>Historique local <i>＋</i></span></summary><div id="observed-signals">'+observedRows()+'</div></details>';}
function updateInsights(m){updateAI(m);updateTechnology(m);swap('#idea-list',ideaCards(m));swap('#news-list',newsRows());swap('#news-status',newsStatus());swap('#strategy-catalog',catalogRows(m));swap('#strategy-count',String(state.strategyCatalog?.length??m.signals?.length??0));swap('#observed-signals',observedRows());swap('#hold-context',holdContext(m));}

function radar(){const m=selected();if(!m)return '<div class="loading"><i></i></div>';renderedSymbol=symbol;return '<div id="desk">'+markets()+'<div class="quote-row" id="instrument-head">'+instrument(m)+'</div><section class="chart-card"><div class="chart-topline"><div class="chart-controls"><span class="timeframe">15m</span><button data-zoom="-1" aria-label="Zoomer">＋</button><button data-zoom="1" aria-label="Dézoomer">−</button><button data-reset-chart aria-label="Réinitialiser le graphique">↺</button><span class="legend"><i></i>EMA 21</span></div><span id="session-state" class="feed-chip"><i></i>'+feedLabel(m)+'</span></div><div class="chart-container"><div class="chart-ohlc" id="chart-ohlc"></div><canvas id="price-chart" role="img" aria-label="Graphique chandeliers '+esc(symbol)+' : prix réels, bougie active et EMA 21"></canvas></div><div class="signal-dock" id="signal-card">'+signalCard(m)+'</div><div class="hold-context" id="hold-context">'+holdContext(m)+'</div></section><div class="market-foot" id="market-foot">'+footer(m)+'</div><section class="model-sheet" id="model-sheet" '+(modelOpen?'':'hidden')+'>'+modelSheet()+'</section>'+insights(m)+'</div>';}
function updateDesk(){const m=selected();swap('#instrument-head',instrument(m));swap('#signal-card',signalCard(m));swap('#market-foot',footer(m));if(modelOpen)swap('#model-sheet',modelSheet());setStatus();drawChart();updateInsights(m);}
function journal(){const open=state.positions.filter(p=>p.status==='open'),closed=state.positions.filter(p=>p.status==='closed'),wr=closed.length?closed.filter(p=>p.pnl>0).length/closed.length*100:null;positionsKey=JSON.stringify(state.positions);return heading('Journal','Simulation locale')+'<div class="stats">'+[['Positions ouvertes',open.length],['Trades clôturés',closed.length],['Win rate net',num(wr,1)+' %'],['Résultat réalisé',money(state.account.realized)]].map(([k,v])=>'<div class="stat"><span>'+k+'</span><b>'+v+'</b></div>').join('')+'</div><div class="panel"><div class="panel-head"><h2>Opérations</h2><span class="pill">PAPER</span></div>'+(state.positions.length?'<div class="table-wrap"><table><thead><tr><th>Marché</th><th>Signal</th><th>Entrée</th><th>Stop</th><th>Objectif</th><th>Résultat</th><th></th></tr></thead><tbody>'+state.positions.map(p=>'<tr><td>'+esc(p.symbol)+'<small>'+date(p.openedAt)+'</small></td><td>'+badge(p.side)+'</td><td class="num">'+price(p.entry,p.symbol)+'</td><td class="num">'+price(p.stop,p.symbol)+'</td><td class="num">'+price(p.target,p.symbol)+'</td><td class="num">'+(p.status==='open'?'Ouverte':money(p.pnl))+'</td><td>'+(p.status==='open'?'<button data-close="'+esc(p.id)+'">Clôturer</button>':esc(p.reason))+'</td></tr>').join('')+'</tbody></table></div>':'<div class="empty">Aucune opération.</div>')+'<details class="details"><summary>Conditions de simulation</summary><p>Paper local, distinct d’Alpaca. Frais 10 bps et glissement 5 bps par côté. Sans levier. Stops suivis sur les cotations reçues ; une coupure ou un gap peut modifier la sortie. Surveillance pendant que le serveur fonctionne.</p></details></div>';}
function challenge(){const p=state.profile,a=state.account,field=(k,label,step='.1')=>'<label>'+label+'<input type="number" name="'+k+'" step="'+step+'" value="'+p[k]+'" required></label>';return heading('Mon challenge','Profil personnalisé')+'<div class="form-layout"><form class="panel form" id="profile-form"><h2>Règles & risque</h2><div class="form-grid"><label>Nom<input name="name" value="'+esc(p.name)+'" maxlength="80" required></label>'+field('capital','Capital ($)','1')+field('targetPercent','Objectif (%)')+field('dailyLossPercent','Perte jour max (%)')+field('totalLossPercent','Perte totale fixe (%)')+field('riskPercent','Risque / trade (%)','.01')+field('openRiskPercent','Risque ouvert max (%)','.01')+field('minDays','Jours minimum','1')+'<label>Fuseau de remise à zéro<select name="resetTimezone">'+['Africa/Casablanca','Europe/Prague','Europe/London','America/New_York','UTC'].map(t=>'<option '+(t===p.resetTimezone?'selected':'')+'>'+t+'</option>').join('')+'</select></label></div><fieldset><legend>Instruments autorisés</legend><div class="checks">'+['EUR/USD','GBP/USD','USD/JPY','XAU/USD','BTC/USD','ETH/USD','SPY','QQQ','NDX'].map(s=>'<label><input type="checkbox" name="allowedSymbols" value="'+s+'" '+(p.allowedSymbols.includes(s)?'checked':'')+'>'+s+'</label>').join('')+'</div></fieldset><label class="confirm"><input type="checkbox" name="confirmed" '+(p.confirmed?'checked':'')+'>Règles et instruments vérifiés</label><button class="primary" type="submit"><span>Enregistrer le profil</span>↗</button><details class="details"><summary>Calcul des limites</summary><p>Perte totale fixe, sans trailing drawdown ni règle de consistance. Référence quotidienne : équité au premier accès du jour dans le fuseau choisi. Capital et fuseau verrouillés après le premier trade. Le profil ne représente pas un compte de firme connecté.</p></details></form><section class="panel plan"><h2>'+esc(p.name)+'</h2><span class="eyebrow">PROGRESSION</span><div class="bar"><span style="width:'+Math.min(100,Math.max(0,100*(a.equity-a.capital)/a.target))+'%"></span></div>'+[['Gain réalisé + latent',money(a.equity-a.capital)],['Objectif restant',money(a.remaining)],['Perte jour / limite',money(a.dayLoss)+' / '+money(p.capital*p.dailyLossPercent/100)],['Perte totale / limite',money(a.totalLoss)+' / '+money(p.capital*p.totalLossPercent/100)],['Jours observés / minimum',a.tradingDays+' / '+p.minDays]].map(([k,v])=>'<div class="row"><span>'+k+'</span><b>'+v+'</b></div>').join('')+'</section></div>';}

function sources(){return heading('Connexions','Origine des cotations')+'<div class="source-grid">'+state.radar.map(m=>'<section class="source-card"><h2>'+esc(names[m.symbol]?.[1]??m.symbol)+'</h2><div class="source-status">'+esc(feedLabel(m))+'</div><details><summary>Source & horodatage</summary><p>'+esc(m.source)+'<br>'+esc(date(m.quote?.eventTime??m.quote?.receivedAt??m.asOf))+'<br>'+esc(m.provenance?.instrumentType??'')+'</p><p>'+esc(m.provenance?.mode??'')+' · '+esc(m.provenance?.providerSymbol??m.symbol)+'</p></details></section>').join('')+'</div><details class="details"><summary>Fonctionnement</summary><p>Bitcoin : Kraken. Forex et or : cotations Deriv public. Nasdaq : indice NDX du fournisseur indiqué, avec son horodatage. Le serveur transmet automatiquement l’état chaque seconde ; le cours change uniquement lors de la réception de données. Aucun prix n’est interpolé.</p><p>Les diagnostics du modèle utilisent un découpage chronologique : 50 % entraînement, 25 % calibration, 25 % test, avec séparation des horizons.</p></details>';}
function render(){if(!state)return;$('#view').innerHTML=tab==='radar'?radar():tab==='journal'?journal():tab==='challenge'?challenge():sources();document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));setStatus();if(tab==='radar'){bindChart();drawChart();}}
function chartBars(){const m=selected();if(!m)return [];return [...m.bars,...(m.currentBar&&Date.parse(m.currentBar.time)>Date.parse(m.bars.at(-1)?.time??0)?[m.currentBar]:[])];}
function drawChart(){const c=$('#price-chart'),m=selected();if(!c||!m)return;const rect=c.getBoundingClientRect(),w=rect.width,h=rect.height,scale=window.devicePixelRatio||1;if(w<1||h<1)return;if(c.width!==Math.round(w*scale)||c.height!==Math.round(h*scale)){c.width=Math.round(w*scale);c.height=Math.round(h*scale);}const ctx=c.getContext('2d');ctx.setTransform(scale,0,0,scale,0,0);ctx.clearRect(0,0,w,h);const all=chartBars();if(!all.length){ctx.fillStyle='#778298';ctx.font='12px Segoe UI';ctx.textAlign='center';ctx.fillText('Connexion aux données…',w/2,h/2);return;}const end=Math.max(1,all.length-panOffset),b=all.slice(Math.max(0,end-rangeCount),end),left=12,right=70,top=46,bottom=32,plotW=w-left-right,volumeH=45,plotH=h-top-bottom-volumeH-14,s=confirmed(m),levels=s.side==='HOLD'?[]:[s.stop,s.target],lo=Math.min(...b.map(x=>x.low),...levels),hi=Math.max(...b.map(x=>x.high),...levels),spread=Math.max(hi-lo,hi*.0001),min=lo-spread*.13,max=hi+spread*.13,y=p=>top+(max-p)/(max-min)*plotH,step=plotW/Math.max(b.length,1),x=i=>left+step*(i+.5),font='9px Consolas';ctx.font=font;ctx.strokeStyle='#20242e';ctx.lineWidth=1;ctx.fillStyle='#778298';
for(let i=0;i<5;i++){const v=min+(max-min)*i/4,yy=Math.round(y(v))+.5;ctx.beginPath();ctx.moveTo(left,yy);ctx.lineTo(w-right,yy);ctx.stroke();ctx.fillText(price(v,m.symbol),w-right+9,yy+3);}for(let i=0;i<b.length;i+=Math.max(1,Math.floor(b.length/5))){ctx.strokeStyle='#20242e';ctx.beginPath();ctx.moveTo(x(i),top);ctx.lineTo(x(i),h-bottom);ctx.stroke();ctx.fillStyle='#778298';ctx.fillText(new Intl.DateTimeFormat('fr-FR',{timeZone:'Africa/Casablanca',hour:'2-digit',minute:'2-digit'}).format(new Date(b[i].time)),Math.max(5,x(i)-15),h-12);}
const maxVol=Math.max(1,...b.map(q=>q.volume));b.forEach((q,i)=>{const color=q.close>=q.open?'#477bff':'#b3bdce',xx=x(i),cw=Math.max(2,Math.min(8,step*.58));if(q.closed===false){ctx.fillStyle='#477bff05';ctx.fillRect(xx-step/2,top,step,h-top-bottom);}ctx.strokeStyle=color;ctx.beginPath();ctx.moveTo(xx,y(q.high));ctx.lineTo(xx,y(q.low));ctx.stroke();ctx.fillStyle=color;ctx.fillRect(xx-cw/2,Math.min(y(q.open),y(q.close)),cw,Math.max(1,Math.abs(y(q.open)-y(q.close))));ctx.globalAlpha=.26;ctx.fillRect(xx-cw/2,h-bottom-volumeH*q.volume/maxVol,cw,volumeH*q.volume/maxVol);ctx.globalAlpha=1;});
let ema=all[0]?.close,values=[];all.forEach(q=>{ema=q.close*2/22+ema*20/22;values.push(ema);});ctx.strokeStyle='#68768c';ctx.lineWidth=1;ctx.beginPath();b.forEach((q,i)=>{const yy=y(values[all.indexOf(q)]);if(i===0)ctx.moveTo(x(i),yy);else ctx.lineTo(x(i),yy);});ctx.stroke();
const px=m.quote?.price??b.at(-1)?.close,py=y(px);if(panOffset===0&&py>=top&&py<=top+plotH){ctx.strokeStyle='#477bff55';ctx.setLineDash([3,4]);ctx.beginPath();ctx.moveTo(left,py);ctx.lineTo(w-right,py);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#477bff';ctx.fillRect(w-right+3,py-9,right-6,18);ctx.fillStyle='#ffffff';ctx.font='9px Consolas';ctx.fillText(price(px,m.symbol),w-right+8,py+3);}
if(s.side!=='HOLD')for(const [v,label,color]of [[s.stop,'SL','#e67087'],[s.target,'TP','#477bff']]){const yy=y(v);ctx.strokeStyle=color;ctx.setLineDash([6,5]);ctx.beginPath();ctx.moveTo(left,yy);ctx.lineTo(w-right,yy);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=color;ctx.fillText(label,left+4,yy-5);}
let hovered=b.at(-1);if(crosshair&&crosshair.x>=left&&crosshair.x<=w-right){const i=Math.max(0,Math.min(b.length-1,Math.floor((crosshair.x-left)/step))),xx=x(i);hovered=b[i];ctx.strokeStyle='#68768c';ctx.setLineDash([2,4]);ctx.beginPath();ctx.moveTo(xx,top);ctx.lineTo(xx,h-bottom);ctx.moveTo(left,crosshair.y);ctx.lineTo(w-right,crosshair.y);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#20242e';ctx.fillRect(w-right+3,crosshair.y-9,right-6,18);ctx.fillStyle='#b3bdce';ctx.fillText(price(max-(crosshair.y-top)/plotH*(max-min),m.symbol),w-right+8,crosshair.y+3);}
if(hovered)$('#chart-ohlc').innerHTML='O <span>'+price(hovered.open)+'</span> H <span>'+price(hovered.high)+'</span> L <span>'+price(hovered.low)+'</span> C <span>'+price(hovered.close)+'</span>'+(hovered.closed===false?'<br><em class="live-bar-label">● Bougie active</em>':'');}
function bindChart(){const c=$('#price-chart');if(!c)return;c.addEventListener('pointermove',e=>{const r=c.getBoundingClientRect();crosshair={x:e.clientX-r.left,y:e.clientY-r.top};if(drag){panOffset=Math.max(0,Math.min(chartBars().length-20,drag.offset+Math.round((drag.x-e.clientX)/6)));}drawChart();});c.addEventListener('pointerleave',()=>{if(!drag){crosshair=null;drawChart();}});c.addEventListener('pointerdown',e=>{drag={x:e.clientX,offset:panOffset};c.setPointerCapture(e.pointerId);});c.addEventListener('pointerup',()=>drag=null);c.addEventListener('pointercancel',()=>drag=null);c.addEventListener('wheel',e=>{e.preventDefault();rangeCount=Math.max(20,Math.min(150,rangeCount+(e.deltaY>0?6:-6)));drawChart();},{passive:false});}

document.addEventListener('click',async e=>{const nav=e.target.closest('[data-tab]'),market=e.target.closest('[data-symbol]'),zoom=e.target.closest('[data-zoom]'),close=e.target.closest('[data-close]');try{if(nav){tab=nav.dataset.tab;render();}if(market){symbol=market.dataset.symbol;panOffset=0;crosshair=null;diagnostics=null;tab='radar';render();}if(zoom){rangeCount=Math.max(20,Math.min(150,rangeCount+Number(zoom.dataset.zoom)*10));drawChart();}if(e.target.closest('[data-reset-chart]')){rangeCount=58;panOffset=0;crosshair=null;drawChart();}if(e.target.closest('[data-model]')){modelOpen=true;$('#model-sheet').hidden=false;swap('#model-sheet',modelSheet());try{diagnostics=await api('/api/model?symbol='+encodeURIComponent(symbol));swap('#model-sheet',modelSheet());}catch{}}if(e.target.closest('[data-dismiss-model]')){modelOpen=false;$('#model-sheet').hidden=true;}if(e.target.closest('#paper-open')&&!busy&&!blocked(selected())){busy=true;await api('/api/paper/open',{symbol,strategy:decision(selected()).strategy});await load();notify('Position paper ouverte.');}if(close&&!busy){busy=true;await api('/api/paper/close',{id:close.dataset.close});await load();notify('Position paper clôturée.');}}catch(err){notify(err.message,true);}finally{busy=false;}});
document.addEventListener('submit',async e=>{if(e.target.id!=='profile-form')return;e.preventDefault();const fd=new FormData(e.target),p={...state.profile};for(const k of ['capital','targetPercent','dailyLossPercent','totalLossPercent','riskPercent','openRiskPercent','minDays'])p[k]=Number(fd.get(k));p.name=fd.get('name');p.resetTimezone=fd.get('resetTimezone');p.allowedSymbols=fd.getAll('allowedSymbols');p.confirmed=fd.has('confirmed');try{await api('/api/profile',p);await load();render();notify('Profil enregistré.');}catch(err){notify(err.message,true);}});
window.addEventListener('resize',()=>drawChart());
const source=new EventSource('/api/stream');source.addEventListener('state',e=>{try{const next=JSON.parse(e.data);if(!validStreamState(next))throw Error('État incomplet');acceptStreamState(next);}catch{streamConnected=false;setStatus();notify('Événement de flux invalide.',true);}});source.onopen=()=>{streamConnected=false;setStatus();};source.onerror=()=>{streamConnected=false;setStatus();};
load().catch(e=>{notify(e.message,true);$('#view').innerHTML='<div class="empty">Connexion au terminal…</div>';});setInterval(()=>{setStatus();if(!pushFresh()&&Date.now()-lastStreamAt>15000&&Date.now()-lastFallbackAt>15000&&!busy){lastFallbackAt=Date.now();load().catch(()=>{});}},1000);

document.addEventListener('click',e=>{const more=e.target.closest('[data-news-more]');if(more){newsExpanded=!newsExpanded;swap('#news-list',newsRows());more.textContent=(newsExpanded?'Réduire':'Toutes les actualités')+' ↗';}});

// Presentation only: no price interpolation, signal calculation or network access.
(()=>{
  if(typeof MutationObserver==='undefined'||typeof document.documentElement?.animate!=='function'||typeof window.matchMedia!=='function')return;
  const root=document.documentElement,view=document.querySelector('#view');if(!view)return;
  const reduced=window.matchMedia('(prefers-reduced-motion: reduce)'),fine=window.matchMedia('(hover: hover) and (pointer: fine)');
  const seen=new WeakSet(),positions=new Map(),prices=new Map(),running=new Set();let queued=false,hoverFrame=0,pointer=null,mode='auto';
  try{const saved=localStorage.getItem('orivane.motion.v1');if(['auto','on','off'].includes(saved))mode=saved;}catch{}
  const enabled=()=>mode==='on'||mode!=='off'&&!reduced.matches;
  const allowed=()=>enabled()&&!document.hidden;
  const holder=document.querySelector('.header-actions');
  if(holder){const toggle=document.createElement('button');toggle.className='motion-toggle';toggle.dataset.motionToggle='';toggle.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" aria-hidden="true"><path d="M3 12h2l3-7 4 14 4-14 3 7h2"/></svg><span>Motion</span>';holder.prepend(toggle);}
  function play(element,frames,options={}){
    if(!allowed()||!element?.isConnected)return null;
    if(running.size>=80)running.values().next().value.cancel();
    const animation=element.animate(frames,{duration:560,easing:'cubic-bezier(.16,1,.3,1)',...options});running.add(animation);
    const clear=()=>running.delete(animation);animation.addEventListener('finish',clear,{once:true});animation.addEventListener('cancel',clear,{once:true});return animation;
  }
  function stop(){for(const animation of running)animation.cancel();running.clear();root.classList.toggle('motion-paused',!allowed());}
  function reveal(element,index=0){
    if(!allowed())return;
    play(element,[{opacity:0,transform:'translateY(18px)'},{opacity:1,transform:'translateY(0)'}],{duration:680,delay:Math.min(index*55,220)});
    if(element.matches('.chart-card'))play(element.querySelector('.chart-container'),[{clipPath:'inset(0 100% 0 0 round 0px)'},{clipPath:'inset(0 0% 0 0 round 0px)'}],{duration:800,delay:80});
  }
  const entrance=typeof IntersectionObserver==='function'?new IntersectionObserver(entries=>{let index=0;for(const entry of entries)if(entry.isIntersecting){entrance.unobserve(entry.target);reveal(entry.target,index++);}},{threshold:.08}):null;
  function selection(selector){
    const track=document.querySelector(selector),active=track?.querySelector('button.active');if(!active)return;
    track.classList.add('motion-track');let marker=track.querySelector(':scope > .motion-selection');
    if(!marker){marker=document.createElement('span');marker.className='motion-selection';marker.setAttribute('aria-hidden','true');track.prepend(marker);}
    const next={x:active.offsetLeft,y:active.offsetTop,w:active.offsetWidth,h:active.offsetHeight},previous=positions.get(selector);
    marker.style.left=next.x+'px';marker.style.top=next.y+'px';marker.style.width=next.w+'px';marker.style.height=next.h+'px';
    if(previous&&(previous.x!==next.x||previous.y!==next.y||previous.w!==next.w||previous.h!==next.h))play(marker,[{transform:'translate('+(previous.x-next.x)+'px,'+(previous.y-next.y)+'px) scale('+previous.w/next.w+','+previous.h/next.h+')'},{transform:'translate(0,0) scale(1,1)'}],{duration:480});
    positions.set(selector,next);
  }
  function refresh(){
    queued=false;root.classList.toggle('motion-paused',!allowed());root.classList.toggle('motion-force',mode==='on');
    const toggle=document.querySelector('[data-motion-toggle]');if(toggle){toggle.setAttribute('aria-pressed',String(enabled()));toggle.setAttribute('aria-label',enabled()?'Réduire les animations':'Activer les animations');toggle.title=enabled()?'Motion activé':'Motion désactivé';}
    root.classList.toggle('motion-live',typeof pushFresh==='function'&&pushFresh()&&selected()?.live===true);
    view.querySelectorAll('.quote-row,.chart-card,.ai-panel,.technology-panel,.insight-panel,.strategy-library,.source-card,.panel,.stat,.page-heading').forEach(element=>{if(seen.has(element))return;seen.add(element);if(entrance)entrance.observe(element);else reveal(element);});
    selection('.market-switcher');selection('header nav');
    const element=view.querySelector('.quote-value b'),key=typeof selected==='function'?selected()?.symbol:null;
    if(element&&key){const value=element.textContent,previous=prices.get(key);prices.set(key,value);if(previous!==undefined&&previous!==value&&root.classList.contains('motion-live'))play(element,[{opacity:.58,textShadow:'0 0 22px #8fb9ff88'},{opacity:1,textShadow:'0 0 0px #8fb9ff00'}],{duration:420});}
  }
  function schedule(){if(!queued){queued=true;requestAnimationFrame(refresh);}}
  new MutationObserver(schedule).observe(view,{childList:true,subtree:true});
  document.addEventListener('click',event=>{if(!event.target.closest('[data-motion-toggle]'))return;mode=enabled()?'off':'on';try{localStorage.setItem('orivane.motion.v1',mode);}catch{}stop();schedule();});
  document.addEventListener('pointerdown',event=>{
    if(!allowed())return;const button=event.target.closest('button');if(!button||button.disabled||!button.isConnected)return;
    const rect=button.getBoundingClientRect(),ripple=document.createElement('i'),size=Math.max(rect.width,rect.height)*1.7;ripple.className='motion-ripple';ripple.setAttribute('aria-hidden','true');
    ripple.style.cssText='width:'+size+'px;height:'+size+'px;left:'+(event.clientX-rect.left-size/2)+'px;top:'+(event.clientY-rect.top-size/2)+'px;';button.classList.add('motion-button');button.append(ripple);
    const animation=play(ripple,[{transform:'scale(.05)',opacity:.32},{transform:'scale(1)',opacity:0}],{duration:520,easing:'cubic-bezier(.2,.6,.3,1)'});if(animation){animation.addEventListener('finish',()=>ripple.remove(),{once:true});animation.addEventListener('cancel',()=>ripple.remove(),{once:true});}else ripple.remove();
  },{passive:true});
  document.addEventListener('pointermove',event=>{
    if(!allowed()||!fine.matches)return;
    const card=event.target.closest('.ai-panel,.technology-panel,.insight-panel');if(!card)return;pointer={card,x:event.clientX,y:event.clientY};
    if(!hoverFrame)hoverFrame=requestAnimationFrame(()=>{hoverFrame=0;if(!pointer?.card.isConnected)return;const rect=pointer.card.getBoundingClientRect();pointer.card.style.setProperty('--light-x',(pointer.x-rect.left)+'px');pointer.card.style.setProperty('--light-y',(pointer.y-rect.top)+'px');});
  },{passive:true});
  document.addEventListener('toggle',event=>{const detail=event.target;if(!detail.matches?.('details')||!detail.open)return;for(const child of detail.children)if(child.tagName!=='SUMMARY')play(child,[{opacity:0,transform:'translateY(-7px)'},{opacity:1,transform:'translateY(0)'}],{duration:320});},true);
  window.addEventListener('resize',schedule,{passive:true});document.addEventListener('visibilitychange',()=>{stop();schedule();});
  reduced.addEventListener('change',()=>{stop();schedule();});
  root.classList.add('motion-ready');schedule();
})();
